  22: static int fcounts(const u8*p,const u8*e,short*norm,int max,int maxlog,int*log,int*used){FBit b;int s=0,last=-1,nb,z,k,threshold,mx;u32 rem,v,lo;memset(norm,0,(size_t)(max+1)*sizeof(*norm));b.p=p;b.end=e;b.bit=0;b.bad=0;*log=(int)fg(&b,4)+5;if(b.bad||*log>maxlog)return 0;rem=(1U<<*log)+1;threshold=1<<*log;nb=*log+1;while(rem>1&&s<=max){mx=(2*threshold-1)-(int)rem;if(mx<0||mx>=2*threshold)return 0;lo=fg(&b,nb-1);if((int)lo<mx)v=lo;else{v=lo|(fg(&b,1)<<(nb-1));if((int)v>=threshold)v-=(u32)mx;}norm[s]=(short)((int)v-1);last=s;if(norm[s]<0)rem--;else rem-=(u32)norm[s];if(rem<1)return 0;if(norm[s]==0){do{z=(int)fg(&b,2);if(s+z>max)return 0;for(k=0;k<z;k++)norm[++s]=0;}while(z==3);}s++;nb=hb(rem)+1;threshold=1<<(nb-1);}if(b.bad||rem!=1||last<0)return 0;*used=(int)((b.bit+7)/8);return *used>0&&p+*used<=e;}
  23: static int fbuild(FTable*t,const short*norm,int max,int log){int sz=1<<log,high=sz-1,pos=0,step=(sz>>1)+(sz>>3)+3,sn[256],i,s,k,ns,bits;u16 sy[FSE_MAX];if(sz>FSE_MAX||max>=256)return 0;for(i=0;i<sz;i++)sy[i]=0xffff;for(s=0;s<=max;s++){sn[s]=norm[s]<0?1:norm[s];if(norm[s]<-1)return 0;}for(s=0;s<=max;s++)if(norm[s]==-1){if(high<0)return 0;sy[high--]=(u16)s;}for(s=0;s<=max;s++)for(k=0;k<norm[s];k++){while(pos>high)pos=(pos+step)&(sz-1);sy[pos]=(u16)s;pos=(pos+step)&(sz-1);}for(i=0;i<sz;i++){if(sy[i]==0xffff)return 0;s=sy[i];ns=sn[s]++;bits=log-hb((u32)ns);if(bits<0||bits>log)return 0;t->c[i].sym=(u16)s;t->c[i].bits=(u8)bits;t->c[i].next=(u16)((ns<<bits)-sz);}t->log=log;t->valid=1;return 1;}
  24: static int freadt(FTable*t,const u8*p,const u8*e,int max,int maxlog,int*used){short n[256];int l,u;if(!fcounts(p,e,n,max,maxlog,&l,&u)||!fbuild(t,n,max,l))return 0;*used=u;return 1;} static int frle(FTable*t,int s){memset(t,0,sizeof(*t));t->valid=1;t->c[0].sym=(u16)s;return 1;} static u32 fs(const FTable*t,u32 s){return t->c[s].sym;}static u32 fn(const FTable*t,u32 s,RBit*b){return t->log?t->c[s].next+rg(b,t->c[s].bits):0;}
