  26: static void hr(HTable*h){memset(h,0,sizeof(*h));h->n[0].child[0]=h->n[0].child[1]=-1;h->n[0].sym=-1;h->used=1;}static int hi(HTable*h,u32 c,int nb,int sym){int x=0,i,bit,y;for(i=nb-1;i>=0;i--){bit=(c>>i)&1;y=h->n[x].child[bit];if(y<0){if(h->used>=HNODES)return 0;y=h->used++;h->n[y].child[0]=h->n[y].child[1]=-1;h->n[y].sym=-1;h->n[x].child[bit]=y;}x=y;}if(h->n[x].sym>=0)return 0;h->n[x].sym=sym;return 1;}
  27: static int hm(HTable*h,u8*w,int nw){u32 sum=0,top=1,rest,code=0;int i,j,mw,prev=-1,nb;for(i=0;i<nw;i++)if(w[i]){if(w[i]>15)return 0;sum+=1U<<(w[i]-1);}if(!sum||nw>255)return 0;while(top<sum)top<<=1;rest=top-sum;if(!rest)return 0;w[nw++]=(u8)(hb(rest)+1);mw=hb(top);hr(h);for(j=1;j<=mw;j++)for(i=0;i<nw;i++)if(w[i]==j){nb=mw+1-j;if(prev<0){prev=nb;code=0;}else{code=(code+1)>>(prev-nb);prev=nb;}if(!hi(h,code,nb,i))return 0;}h->valid=1;h->maxbits=mw;return 1;}
