  29: static int hwf(u8*w,int*nw,const u8*p,size_t n){FTable t;int u,count=0,guard=0;RBit b;u32 a,c;if(!freadt(&t,p,p+n,255,6,&u)||u>=(int)n||!ri(&b,p+u,n-(size_t)u))return 0;a=rg(&b,t.log);c=rg(&b,t.log);while(b.pos&&count<253&&guard++<512){w[count++]=(u8)fs(&t,a);if(b.pos<t.c[a].bits){a=t.c[a].next;break;}a=fn(&t,a,&b);if(!b.pos)break;w[count++]=(u8)fs(&t,c);if(b.pos<t.c[c].bits){c=t.c[c].next;break;}c=fn(&t,c,&b);}if(count<255)w[count++]=(u8)fs(&t,a);if(count<255)w[count++]=(u8)fs(&t,c);*nw=count;return count>0;}
  30: static int hread(HTable*h,const u8*p,const u8*e,int*used){int n,i;u8 w[256];if(p>=e)return 0;if(*p>=128){n=*p-127;if(!need(p+1,e,(size_t)((n+1)/2)))return 0;for(i=0;i<n;i++)w[i]=(i&1)?(p[1+i/2]&15):(p[1+i/2]>>4);*used=1+(n+1)/2;}else{n=*p;if(n<2||!need(p+1,e,(size_t)n)||!hwf(w,&i,p+1,(size_t)n))return 0;n=i;*used=1+*p;}return hm(h,w,n);}
