  32: static int put(DCtx*d,u8 c){if(d->pos>=d->cap)return 0;d->out[d->pos++]=c;return 1;}static int raw(DCtx*d,const u8*p,size_t n){if(n>d->cap-d->pos)return 0;memcpy(d->out+d->pos,p,n);d->pos+=n;return 1;}static int mt(DCtx*d,u32 off,size_t n){size_t made=d->pos-d->frame_start,i;u8 c;if(!off||off>d->window||off>made+d->dict_len||(made>d->window&&off>made))return 0;for(i=0;i<n;i++){if(off<=d->pos-d->frame_start)c=d->out[d->pos-off];else{size_t back=(size_t)off-(d->pos-d->frame_start);if(back>d->dict_len)return 0;c=d->dict[d->dict_len-back];}if(!put(d,c))return 0;}return 1;}
