  36: static int seq(DCtx*d,const u8*p,const u8*e,const u8*lit,size_t ln){u32 ns,ls,os,ms,lc,oc,mc,lv,mv,ov;int lm,om,mm,lb,mb;size_t used=0;RBit b;FTable pl,po,pm;if(p>=e)return 0;ns=*p++;if(ns==0)return raw(d,lit,ln);if(ns>=128){if(p>=e)return 0;if(ns<255)ns=((ns-128)<<8)|*p++;else{if(!need(p,e,2))return 0;ns=(u32)p[0]+((u32)p[1]<<8)+0x7f00;p+=2;}}if(p>=e)return 0;lm=(*p>>6)&3;om=(*p>>4)&3;mm=(*p>>2)&3;if((*p++&3))return 0;pd(&pl,&po,&pm);if(!tmode(&d->ll,lm,&p,e,35,9,&pl)||!tmode(&d->of,om,&p,e,31,8,&po)||!tmode(&d->ml,mm,&p,e,52,9,&pm)){fprintf(stderr,"table fail %d%d%d\\n",lm,om,mm);return 0;}fprintf(stderr,"seq n=%u mode=%d%d%d logs=%d%d%d bits=%zu\\n",ns,lm,om,mm,d->ll.log,d->of.log,d->ml.log,(size_t)(e-p));d->seq_valid=1;if(!ri(&b,p,(size_t)(e-p)))return 0;ls=d->ll.log?rg(&b,d->ll.log):0;os=d->of.log?rg(&b,d->of.log):0;ms=d->ml.log?rg(&b,d->ml.log):0;while(ns--){lc=fs(&d->ll,ls);oc=fs(&d->of,os);mc=fs(&d->ml,ms);if(oc>31)return 0;ov=(1U<<oc)+rg(&b,(int)oc);mp(mc,&mv,&mb);mv+=rg(&b,mb);lp(lc,&lv,&lb);lv+=rg(&b,lb);if(!ex(d,lit+used,ln-used,lv,ov,mv)){fprintf(stderr,"ex fail lc=%u oc=%u mc=%u lv=%u ov=%u mv=%u used=%zu\\n",lc,oc,mc,lv,ov,mv,used);return 0;}used+=lv;if(ns){ls=fn(&d->ll,ls,&b);ms=fn(&d->ml,ms,&b);os=fn(&d->of,os,&b);}}fprintf(stderr,"end b=%zu bad=%d used=%zu\\n",b.pos,b.bad,used);return !b.bad&&b.pos==0&&raw(d,lit+used,ln-used);}
